INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'barcelona', 'service', 'checklist', 'positive', 'Checklist 100/100 electricistas barcelona', 100, 'v80_9e5c793c996ad31b', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a diferencial, magnetotérmico o línea afectada.</li><li>Confirmar barrio o zona de Barcelona, por ejemplo Gràcia o Sants.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 51}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9e5c793c996ad31b' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'barcelona', 'service', 'map', 'positive', 'Map 100/100 electricistas barcelona', 100, 'v80_fc1ef5a67ddd523d', '<h2>Cobertura local en Barcelona</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para electricistas, tiene sentido organizar la disponibilidad alrededor de Sant Martí, Poblenou, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 41}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_fc1ef5a67ddd523d' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'barcelona', 'service', 'content', 'positive', 'Content 100/100 electricistas barcelona', 100, 'v80_b70526d6654ccfd7', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención eléctrica bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, aislar la avería, revisar línea afectada y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_b70526d6654ccfd7' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'barcelona', 'service', 'urgency_panel', 'positive', 'Urgency Panel 100/100 electricistas barcelona', 100, 'v80_78fe600c4b80ef0c', '<h2>Atención prioritaria sin alarmismo</h2><p>Si el problema afecta a seguridad, suministro, acceso o daños en curso, conviene priorizar la revisión. Aun así, la urgencia no justifica promesas vagas: se debe confirmar zona de Barcelona, síntoma, posible riesgo y margen de actuación antes de enviar al profesional.</p><p><strong>Acción:</strong> Solicitar atención prioritaria</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 48}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_78fe600c4b80ef0c' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'hero_trust', 'positive', 'Hero Trust 100/100 electricistas valencia', 100, 'v80_8f3f1e44e9d8c2ec', '<h1>Electricistas en Valencia con diagnóstico claro antes de intervenir</h1><p>Servicio orientado a resolver cortes de suministro, derivaciones o protecciones que saltan sin causa clara con una valoración previa, explicación sencilla y actuación proporcionada al estado real de la vivienda, local o comunidad.</p><ul><li>Revisión inicial de enchufe, cableado y señales visibles del problema.</li><li>Presupuesto condicionado al alcance real, sin inventar urgencias ni datos no confirmados.</li><li>Cobertura en Avenida del Cid, Ruzafa y otras zonas de Valencia según disponibilidad.</li></ul><p><strong>CTA:</strong> Solicitar valoración técnica</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 76}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_8f3f1e44e9d8c2ec' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'services_grid', 'positive', 'Services Grid 100/100 electricistas valencia', 100, 'v80_001d34be661ee7b5', '<h2>Servicios de electricistas con criterio técnico</h2><ul><li><strong>Cableado:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Cuadro eléctrico:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Diferencial:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_001d34be661ee7b5' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'process_steps', 'positive', 'Process Steps 100/100 electricistas valencia', 100, 'v80_655d16416520d834', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Valencia, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe medir carga, aislar la avería y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe diagnosticar el circuito y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 65}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_655d16416520d834' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'faq', 'positive', 'Faq 100/100 electricistas valencia', 100, 'v80_2c0e8c1a09bd57f1', '<h3>¿Qué datos conviene facilitar antes de pedir un electricista en Valencia?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: diferencial, magnetotérmico o línea afectada. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 79}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_2c0e8c1a09bd57f1' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 electricistas valencia', 100, 'v80_9945e4ff92cf1252', '<h2>Qué influye en el presupuesto</h2><p>En Valencia, el precio de una intervención eléctrica depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de magnetotérmico que una sustitución con ajustes sobre línea afectada o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 64}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9945e4ff92cf1252' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valencia', 'service', 'local_proof', 'positive', 'Local Proof 100/100 electricistas valencia', 100, 'v80_b9a6ca7cd80ce093', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por El Carmen, Avenida del Cid y el entorno urbano de Valencia, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 62}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_b9a6ca7cd80ce093' AND agent_name = 'Content_Writer_01');
