INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 electricistas bilbao', 100, 'v80_d0533f5922917855', '<h2>Qué influye en el presupuesto</h2><p>En Bilbao, el precio de una intervención eléctrica depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de enchufe que una sustitución con ajustes sobre cableado o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_d0533f5922917855' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'local_proof', 'positive', 'Local Proof 100/100 electricistas bilbao', 100, 'v80_0e99ac7dc156bbc1', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por Zorrotza, Deusto y el entorno urbano de Bilbao, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 59}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_0e99ac7dc156bbc1' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'trust_band', 'positive', 'Trust Band 100/100 electricistas bilbao', 100, 'v80_f580adef3c3e4cf2', '<h2>Garantías prudentes y trabajo responsable</h2><p>Un servicio fiable no promete resultados absolutos sin revisar el caso. Debe trabajar con criterios de REBT y criterios de seguridad eléctrica aplicables, explicar limitaciones y evitar datos comerciales no confirmados. La confianza se construye con claridad: qué se hará, qué no se puede asegurar y qué comprobaciones se realizarán al finalizar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_f580adef3c3e4cf2' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'cta_panel', 'positive', 'Cta Panel 100/100 electricistas bilbao', 100, 'v80_9733f7edb5898781', '<h2>¿Necesita valorar una intervención eléctrica en Bilbao?</h2><p>Explique el síntoma, la zona y si el problema afecta a diferencial, magnetotérmico o línea afectada. Con esa información se puede orientar la intervención y preparar una propuesta más precisa.</p><p><strong>Botón:</strong> Solicitar valoración</p><p><small>Sin promesas automáticas: primero se revisa el caso y después se confirma el alcance.</small></p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 51}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9733f7edb5898781' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'comparison_table', 'positive', 'Comparison Table 100/100 electricistas bilbao', 100, 'v80_38643158d2f6e99a', '<h2>Reparar, ajustar o sustituir</h2><table><tr><th>Opción</th><th>Cuándo encaja</th><th>Qué comprobar</th></tr><tr><td>Reparar</td><td>Cuando el fallo está localizado y el elemento conserva vida útil.</td><td>Magnetotérmico y señales de desgaste.</td></tr><tr><td>Ajustar</td><td>Cuando el problema viene de uso, holgura, presión o configuración.</td><td>Revisar protecciones y repetir la prueba.</td></tr><tr><td>Sustituir</td><td>Cuando hay rotura, incompatibilidad o riesgo persistente.</td><td>Material compatible, seguridad y comprobación final.</td></tr></table>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 45}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_38643158d2f6e99a' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'checklist', 'positive', 'Checklist 100/100 electricistas bilbao', 100, 'v80_084eef09658171a9', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a línea afectada, punto de luz o enchufe.</li><li>Confirmar barrio o zona de Bilbao, por ejemplo Abando o Begoña.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 53}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_084eef09658171a9' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'map', 'positive', 'Map 100/100 electricistas bilbao', 100, 'v80_6e9f9703b2e7c203', '<h2>Cobertura local en Bilbao</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para electricistas, tiene sentido organizar la disponibilidad alrededor de Casco Viejo, Zorrotza, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 41}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_6e9f9703b2e7c203' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'content', 'positive', 'Content 100/100 electricistas bilbao', 100, 'v80_9da2bd6111dfaa48', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención eléctrica bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, aislar la avería, revisar enchufe y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 62}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9da2bd6111dfaa48' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'bilbao', 'service', 'urgency_panel', 'positive', 'Urgency Panel 100/100 electricistas bilbao', 100, 'v80_16c67e4ae833a4a8', '<h2>Atención prioritaria sin alarmismo</h2><p>Si el problema afecta a seguridad, suministro, acceso o daños en curso, conviene priorizar la revisión. Aun así, la urgencia no justifica promesas vagas: se debe confirmar zona de Bilbao, síntoma, posible riesgo y margen de actuación antes de enviar al profesional.</p><p><strong>Acción:</strong> Solicitar atención prioritaria</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 48}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_16c67e4ae833a4a8' AND agent_name = 'Content_Writer_01');
