INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'zaragoza', 'service', 'content', 'positive', 'Content 100/100 electricistas zaragoza', 100, 'v80_4c2c7321b4e293c0', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención eléctrica bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, comprobar continuidad, revisar punto de luz y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_4c2c7321b4e293c0' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'zaragoza', 'service', 'urgency_panel', 'positive', 'Urgency Panel 100/100 electricistas zaragoza', 100, 'v80_6cd52c95b535fb2c', '<h2>Atención prioritaria sin alarmismo</h2><p>Si el problema afecta a seguridad, suministro, acceso o daños en curso, conviene priorizar la revisión. Aun así, la urgencia no justifica promesas vagas: se debe confirmar zona de Zaragoza, síntoma, posible riesgo y margen de actuación antes de enviar al profesional.</p><p><strong>Acción:</strong> Solicitar atención prioritaria</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 48}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_6cd52c95b535fb2c' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'hero_trust', 'positive', 'Hero Trust 100/100 electricistas alicante', 100, 'v80_eed6cee289db9e8c', '<h1>Electricistas en Alicante con diagnóstico claro antes de intervenir</h1><p>Servicio orientado a resolver cortes de suministro, derivaciones o protecciones que saltan sin causa clara con una valoración previa, explicación sencilla y actuación proporcionada al estado real de la vivienda, local o comunidad.</p><ul><li>Revisión inicial de cableado, cuadro eléctrico y señales visibles del problema.</li><li>Presupuesto condicionado al alcance real, sin inventar urgencias ni datos no confirmados.</li><li>Cobertura en Ensanche, Carolinas y otras zonas de Alicante según disponibilidad.</li></ul><p><strong>CTA:</strong> Solicitar valoración técnica</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 75}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_eed6cee289db9e8c' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'services_grid', 'positive', 'Services Grid 100/100 electricistas alicante', 100, 'v80_3a70e00c9c9cda21', '<h2>Servicios de electricistas con criterio técnico</h2><ul><li><strong>Cuadro eléctrico:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Diferencial:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Magnetotérmico:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_3a70e00c9c9cda21' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'process_steps', 'positive', 'Process Steps 100/100 electricistas alicante', 100, 'v80_1faae71977139256', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Alicante, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe revisar protecciones, comprobar continuidad y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe medir carga y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_1faae71977139256' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'faq', 'positive', 'Faq 100/100 electricistas alicante', 100, 'v80_78912b32caa5912f', '<h3>¿Qué datos conviene facilitar antes de pedir un electricista en Alicante?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: magnetotérmico, línea afectada o punto de luz. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 81}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_78912b32caa5912f' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 electricistas alicante', 100, 'v80_637a5094f6eaae50', '<h2>Qué influye en el presupuesto</h2><p>En Alicante, el precio de una intervención eléctrica depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de línea afectada que una sustitución con ajustes sobre punto de luz o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_637a5094f6eaae50' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'local_proof', 'positive', 'Local Proof 100/100 electricistas alicante', 100, 'v80_7d77559e45d8e31e', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por Centro, Ensanche y el entorno urbano de Alicante, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 59}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_7d77559e45d8e31e' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'alicante', 'service', 'trust_band', 'positive', 'Trust Band 100/100 electricistas alicante', 100, 'v80_4f66617ed8f91d7d', '<h2>Garantías prudentes y trabajo responsable</h2><p>Un servicio fiable no promete resultados absolutos sin revisar el caso. Debe trabajar con criterios de REBT y criterios de seguridad eléctrica aplicables, explicar limitaciones y evitar datos comerciales no confirmados. La confianza se construye con claridad: qué se hará, qué no se puede asegurar y qué comprobaciones se realizarán al finalizar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_4f66617ed8f91d7d' AND agent_name = 'Content_Writer_01');
