INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'local_proof', 'positive', 'Local Proof 100/100 electricistas valladolid', 100, 'v80_5a5e67d4d6dc96a0', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por La Rondilla, Covaresa y el entorno urbano de Valladolid, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 60}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_5a5e67d4d6dc96a0' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'trust_band', 'positive', 'Trust Band 100/100 electricistas valladolid', 100, 'v80_d77a6fc71986e3e5', '<h2>Garantías prudentes y trabajo responsable</h2><p>Un servicio fiable no promete resultados absolutos sin revisar el caso. Debe trabajar con criterios de REBT y criterios de seguridad eléctrica aplicables, explicar limitaciones y evitar datos comerciales no confirmados. La confianza se construye con claridad: qué se hará, qué no se puede asegurar y qué comprobaciones se realizarán al finalizar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_d77a6fc71986e3e5' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'cta_panel', 'positive', 'Cta Panel 100/100 electricistas valladolid', 100, 'v80_0fbc3a09fa3f3024', '<h2>¿Necesita valorar una intervención eléctrica en Valladolid?</h2><p>Explique el síntoma, la zona y si el problema afecta a enchufe, cableado o cuadro eléctrico. Con esa información se puede orientar la intervención y preparar una propuesta más precisa.</p><p><strong>Botón:</strong> Solicitar valoración</p><p><small>Sin promesas automáticas: primero se revisa el caso y después se confirma el alcance.</small></p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 51}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_0fbc3a09fa3f3024' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'comparison_table', 'positive', 'Comparison Table 100/100 electricistas valladolid', 100, 'v80_8018fd1872401556', '<h2>Reparar, ajustar o sustituir</h2><table><tr><th>Opción</th><th>Cuándo encaja</th><th>Qué comprobar</th></tr><tr><td>Reparar</td><td>Cuando el fallo está localizado y el elemento conserva vida útil.</td><td>Cableado y señales de desgaste.</td></tr><tr><td>Ajustar</td><td>Cuando el problema viene de uso, holgura, presión o configuración.</td><td>Diagnosticar el circuito y repetir la prueba.</td></tr><tr><td>Sustituir</td><td>Cuando hay rotura, incompatibilidad o riesgo persistente.</td><td>Material compatible, seguridad y comprobación final.</td></tr></table>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 46}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_8018fd1872401556' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'checklist', 'positive', 'Checklist 100/100 electricistas valladolid', 100, 'v80_84b3a31a466eb9e4', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a cuadro eléctrico, diferencial o magnetotérmico.</li><li>Confirmar barrio o zona de Valladolid, por ejemplo Parquesol o Centro.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 51}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_84b3a31a466eb9e4' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'map', 'positive', 'Map 100/100 electricistas valladolid', 100, 'v80_df08c1ea42bc3b0e', '<h2>Cobertura local en Valladolid</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para electricistas, tiene sentido organizar la disponibilidad alrededor de Delicias, La Rondilla, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 41}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_df08c1ea42bc3b0e' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'content', 'positive', 'Content 100/100 electricistas valladolid', 100, 'v80_faa77a1603ee84d5', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención eléctrica bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, medir carga, revisar magnetotérmico y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 61}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_faa77a1603ee84d5' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'electricistas', 'valladolid', 'service', 'urgency_panel', 'positive', 'Urgency Panel 100/100 electricistas valladolid', 100, 'v80_197e7eeb3fdf9a23', '<h2>Atención prioritaria sin alarmismo</h2><p>Si el problema afecta a seguridad, suministro, acceso o daños en curso, conviene priorizar la revisión. Aun así, la urgencia no justifica promesas vagas: se debe confirmar zona de Valladolid, síntoma, posible riesgo y margen de actuación antes de enviar al profesional.</p><p><strong>Acción:</strong> Solicitar atención prioritaria</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 48}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_197e7eeb3fdf9a23' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'madrid', 'service', 'hero_trust', 'positive', 'Hero Trust 100/100 cerrajeros madrid', 100, 'v80_1b05364a3e3ae172', '<h1>Cerrajeros en Madrid con diagnóstico claro antes de intervenir</h1><p>Servicio orientado a resolver cierres bloqueados, llaves partidas o accesos vulnerables con una valoración previa, explicación sencilla y actuación proporcionada al estado real de la vivienda, local o comunidad.</p><ul><li>Revisión inicial de cilindro, llave partida y señales visibles del problema.</li><li>Presupuesto condicionado al alcance real, sin inventar urgencias ni datos no confirmados.</li><li>Cobertura en Arganzuela, Plaza de Castilla y otras zonas de Madrid según disponibilidad.</li></ul><p><strong>CTA:</strong> Solicitar valoración técnica</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 73}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_1b05364a3e3ae172' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'madrid', 'service', 'services_grid', 'positive', 'Services Grid 100/100 cerrajeros madrid', 100, 'v80_89c91fc365af1138', '<h2>Servicios de cerrajeros con criterio técnico</h2><ul><li><strong>Llave partida:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Puerta acorazada:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Bombín:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 57}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_89c91fc365af1138' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'madrid', 'service', 'process_steps', 'positive', 'Process Steps 100/100 cerrajeros madrid', 100, 'v80_cf1a62bb2fafbc36', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Madrid, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe revisar el bombín, comprobar el cierre y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe evitar daños innecesarios y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_cf1a62bb2fafbc36' AND agent_name = 'Content_Writer_01');
