INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'granada', 'service', 'hero_trust', 'positive', 'Hero Trust 100/100 cerrajeros granada', 100, 'v80_ff26e7ecc2d4cdde', '<h1>Cerrajeros en Granada con diagnóstico claro antes de intervenir</h1><p>Servicio orientado a resolver cierres bloqueados, llaves partidas o accesos vulnerables con una valoración previa, explicación sencilla y actuación proporcionada al estado real de la vivienda, local o comunidad.</p><ul><li>Revisión inicial de bombín, escudo protector y señales visibles del problema.</li><li>Presupuesto condicionado al alcance real, sin inventar urgencias ni datos no confirmados.</li><li>Cobertura en Zaidín, Albaicín y otras zonas de Granada según disponibilidad.</li></ul><p><strong>CTA:</strong> Solicitar valoración técnica</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 71}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_ff26e7ecc2d4cdde' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'granada', 'service', 'services_grid', 'positive', 'Services Grid 100/100 cerrajeros granada', 100, 'v80_2dc479f658a8aa20', '<h2>Servicios de cerrajeros con criterio técnico</h2><ul><li><strong>Escudo protector:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Cerradura multipunto:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Resbalón:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 57}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_2dc479f658a8aa20' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'granada', 'service', 'process_steps', 'positive', 'Process Steps 100/100 cerrajeros granada', 100, 'v80_c0dfcd716bf12d5f', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Granada, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe evitar daños innecesarios, valorar el acceso y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe proteger el marco y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_c0dfcd716bf12d5f' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'granada', 'service', 'faq', 'positive', 'Faq 100/100 cerrajeros granada', 100, 'v80_3d653525ba6c7ffd', '<h3>¿Qué datos conviene facilitar antes de pedir un cerrajero en Granada?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: resbalón, cilindro o llave partida. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 79}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_3d653525ba6c7ffd' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'granada', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 cerrajeros granada', 100, 'v80_8bfd19cf6e3faf45', '<h2>Qué influye en el presupuesto</h2><p>En Granada, el precio de una intervención de cerrajería depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de cilindro que una sustitución con ajustes sobre llave partida o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 65}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_8bfd19cf6e3faf45' AND agent_name = 'Content_Writer_01');
