INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'cta_panel', 'positive', 'Cta Panel 100/100 cerrajeros malaga', 100, 'v80_97e827aa2ca5f4a6', '<h2>¿Necesita valorar una intervención de cerrajería en Malaga?</h2><p>Explique el síntoma, la zona y si el problema afecta a puerta acorazada, bombín o escudo protector. Con esa información se puede orientar la intervención y preparar una propuesta más precisa.</p><p><strong>Botón:</strong> Solicitar valoración</p><p><small>Sin promesas automáticas: primero se revisa el caso y después se confirma el alcance.</small></p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 53}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_97e827aa2ca5f4a6' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'comparison_table', 'positive', 'Comparison Table 100/100 cerrajeros malaga', 100, 'v80_428e588fb28e7f03', '<h2>Reparar, ajustar o sustituir</h2><table><tr><th>Opción</th><th>Cuándo encaja</th><th>Qué comprobar</th></tr><tr><td>Reparar</td><td>Cuando el fallo está localizado y el elemento conserva vida útil.</td><td>Bombín y señales de desgaste.</td></tr><tr><td>Ajustar</td><td>Cuando el problema viene de uso, holgura, presión o configuración.</td><td>Comprobar el cierre y repetir la prueba.</td></tr><tr><td>Sustituir</td><td>Cuando hay rotura, incompatibilidad o riesgo persistente.</td><td>Material compatible, seguridad y comprobación final.</td></tr></table>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 46}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_428e588fb28e7f03' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'checklist', 'positive', 'Checklist 100/100 cerrajeros malaga', 100, 'v80_a50e01d2413b5812', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a escudo protector, cerradura multipunto o resbalón.</li><li>Confirmar barrio o zona de Malaga, por ejemplo El Palo o Carretera de Cádiz.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 55}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_a50e01d2413b5812' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'map', 'positive', 'Map 100/100 cerrajeros malaga', 100, 'v80_a6ef37fafb533866', '<h2>Cobertura local en Malaga</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para cerrajeros, tiene sentido organizar la disponibilidad alrededor de Huelin, Centro, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 40}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_a6ef37fafb533866' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'content', 'positive', 'Content 100/100 cerrajeros malaga', 100, 'v80_c97cf12c2427834c', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención de cerrajería bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, proteger el marco, revisar resbalón y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_c97cf12c2427834c' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'malaga', 'service', 'urgency_panel', 'positive', 'Urgency Panel 100/100 cerrajeros malaga', 100, 'v80_cdf7dce142eb56ad', '<h2>Atención prioritaria sin alarmismo</h2><p>Si el problema afecta a seguridad, suministro, acceso o daños en curso, conviene priorizar la revisión. Aun así, la urgencia no justifica promesas vagas: se debe confirmar zona de Malaga, síntoma, posible riesgo y margen de actuación antes de enviar al profesional.</p><p><strong>Acción:</strong> Solicitar atención prioritaria</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 48}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_cdf7dce142eb56ad' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'bilbao', 'service', 'hero_trust', 'positive', 'Hero Trust 100/100 cerrajeros bilbao', 100, 'v80_be60a67399c810b3', '<h1>Cerrajeros en Bilbao con diagnóstico claro antes de intervenir</h1><p>Servicio orientado a resolver cierres bloqueados, llaves partidas o accesos vulnerables con una valoración previa, explicación sencilla y actuación proporcionada al estado real de la vivienda, local o comunidad.</p><ul><li>Revisión inicial de llave partida, puerta acorazada y señales visibles del problema.</li><li>Presupuesto condicionado al alcance real, sin inventar urgencias ni datos no confirmados.</li><li>Cobertura en Begoña, Indautxu y otras zonas de Bilbao según disponibilidad.</li></ul><p><strong>CTA:</strong> Solicitar valoración técnica</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 72}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_be60a67399c810b3' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'bilbao', 'service', 'services_grid', 'positive', 'Services Grid 100/100 cerrajeros bilbao', 100, 'v80_cfbbbe7038d5acb0', '<h2>Servicios de cerrajeros con criterio técnico</h2><ul><li><strong>Puerta acorazada:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Bombín:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Escudo protector:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 57}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_cfbbbe7038d5acb0' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'bilbao', 'service', 'process_steps', 'positive', 'Process Steps 100/100 cerrajeros bilbao', 100, 'v80_752e5801eb86ade2', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Bilbao, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe valorar el acceso, proteger el marco y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe revisar el bombín y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_752e5801eb86ade2' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'bilbao', 'service', 'faq', 'positive', 'Faq 100/100 cerrajeros bilbao', 100, 'v80_003f5d587f4fe2aa', '<h3>¿Qué datos conviene facilitar antes de pedir un cerrajero en Bilbao?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: escudo protector, cerradura multipunto o resbalón. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 80}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_003f5d587f4fe2aa' AND agent_name = 'Content_Writer_01');
