INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'services_grid', 'positive', 'Services Grid 100/100 cerrajeros zaragoza', 100, 'v80_6387df873df0dd88', '<h2>Servicios de cerrajeros con criterio técnico</h2><ul><li><strong>Llave partida:</strong> se revisa el estado, el síntoma y la causa probable antes de sustituir piezas.</li><li><strong>Puerta acorazada:</strong> la intervención se plantea según uso, antigüedad, accesibilidad y seguridad.</li><li><strong>Bombín:</strong> se comprueba el resultado final para evitar reparaciones incompletas.</li></ul><p>Este enfoque permite diferenciar una reparación puntual de una mejora necesaria y evita presupuestos cerrados sin contexto.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 57}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_6387df873df0dd88' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'process_steps', 'positive', 'Process Steps 100/100 cerrajeros zaragoza', 100, 'v80_e2a756d81a0014d2', '<h2>Cómo se organiza la intervención</h2><ol><li><strong>Escucha y datos mínimos:</strong> ubicación aproximada en Zaragoza, tipo de inmueble y síntoma principal.</li><li><strong>Comprobación técnica:</strong> el profesional debe comprobar el cierre, evitar daños innecesarios y valorar si hay señales de intervención previa.</li><li><strong>Propuesta proporcionada:</strong> se explica si conviene ajustar, reparar o sustituir, con materiales y límites claros.</li><li><strong>Verificación final:</strong> antes de cerrar el trabajo se debe valorar el acceso y dejar recomendaciones de uso.</li></ol>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_e2a756d81a0014d2' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'faq', 'positive', 'Faq 100/100 cerrajeros zaragoza', 100, 'v80_9f0cadac09cf7738', '<h3>¿Qué datos conviene facilitar antes de pedir un cerrajero en Zaragoza?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: bombín, escudo protector o cerradura multipunto. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 80}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9f0cadac09cf7738' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 cerrajeros zaragoza', 100, 'v80_7ce3f714f688640b', '<h2>Qué influye en el presupuesto</h2><p>En Zaragoza, el precio de una intervención de cerrajería depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de escudo protector que una sustitución con ajustes sobre cerradura multipunto o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 66}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_7ce3f714f688640b' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'local_proof', 'positive', 'Local Proof 100/100 cerrajeros zaragoza', 100, 'v80_5cf5411ddb6e23b5', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por Centro, La Romareda y el entorno urbano de Zaragoza, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 60}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_5cf5411ddb6e23b5' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'trust_band', 'positive', 'Trust Band 100/100 cerrajeros zaragoza', 100, 'v80_c8f4cc22cb1f7579', '<h2>Garantías prudentes y trabajo responsable</h2><p>Un servicio fiable no promete resultados absolutos sin revisar el caso. Debe trabajar con criterios de criterios de apertura no destructiva y seguridad residencial, explicar limitaciones y evitar datos comerciales no confirmados. La confianza se construye con claridad: qué se hará, qué no se puede asegurar y qué comprobaciones se realizarán al finalizar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 57}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_c8f4cc22cb1f7579' AND agent_name = 'Content_Writer_01');
