INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'comparison_table', 'positive', 'Comparison Table 100/100 cerrajeros zaragoza', 100, 'v80_d62bc53267b1cff7', '<h2>Reparar, ajustar o sustituir</h2><table><tr><th>Opción</th><th>Cuándo encaja</th><th>Qué comprobar</th></tr><tr><td>Reparar</td><td>Cuando el fallo está localizado y el elemento conserva vida útil.</td><td>Llave partida y señales de desgaste.</td></tr><tr><td>Ajustar</td><td>Cuando el problema viene de uso, holgura, presión o configuración.</td><td>Evitar daños innecesarios y repetir la prueba.</td></tr><tr><td>Sustituir</td><td>Cuando hay rotura, incompatibilidad o riesgo persistente.</td><td>Material compatible, seguridad y comprobación final.</td></tr></table>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 47}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_d62bc53267b1cff7' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'checklist', 'positive', 'Checklist 100/100 cerrajeros zaragoza', 100, 'v80_9dffcc3f6d25fef8', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a puerta acorazada, bombín o escudo protector.</li><li>Confirmar barrio o zona de Zaragoza, por ejemplo Torrero o Actur.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 52}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_9dffcc3f6d25fef8' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'cerrajeros', 'zaragoza', 'service', 'map', 'positive', 'Map 100/100 cerrajeros zaragoza', 100, 'v80_4298a93b38a1a0a7', '<h2>Cobertura local en Zaragoza</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para cerrajeros, tiene sentido organizar la disponibilidad alrededor de Delicias, Centro, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 40}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_4298a93b38a1a0a7' AND agent_name = 'Content_Writer_01');
