INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'faq', 'positive', 'Faq 100/100 fontaneros sevilla', 100, 'v80_15e4f1c98072d90b', '<h3>¿Qué datos conviene facilitar antes de pedir un fontanero en Sevilla?</h3><p>Conviene indicar el barrio, el tipo de inmueble, cuándo apareció el problema y qué elemento parece afectado: sifón, bajante o latiguillo. Con esos datos se puede orientar mejor la visita y evitar presupuestos genéricos.</p><h3>¿Cuándo es mejor reparar y cuándo sustituir?</h3><p>La decisión depende del estado real, la antigüedad, la seguridad y la disponibilidad de piezas compatibles. Un enfoque profesional evita cambiar componentes completos si basta con ajustar o reparar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 78}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_15e4f1c98072d90b' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'price_guidance', 'positive', 'Price Guidance 100/100 fontaneros sevilla', 100, 'v80_1d7885dd0c08738b', '<h2>Qué influye en el presupuesto</h2><p>En Sevilla, el precio de una intervención de fontanería depende del desplazamiento, el horario, la accesibilidad, los materiales y la complejidad del diagnóstico. No es lo mismo una revisión sencilla de bajante que una sustitución con ajustes sobre latiguillo o una actuación urgente con comprobaciones adicionales.</p><p>Un presupuesto serio debe separar mano de obra, materiales, posibles suplementos y condiciones de garantía.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 64}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_1d7885dd0c08738b' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'local_proof', 'positive', 'Local Proof 100/100 fontaneros sevilla', 100, 'v80_7b6e81e386ff63bb', '<h2>Señales de confianza antes de contratar</h2><ul><li><strong>Zona reconocible:</strong> el servicio puede organizar rutas por Macarena, Santa Justa y el entorno urbano de Sevilla, sin fingir una oficina exacta si no está confirmada.</li><li><strong>Diagnóstico explicado:</strong> debe quedar claro qué se revisó y por qué se propone una reparación concreta.</li><li><strong>Resultado verificable:</strong> al terminar, el cliente debe poder comprobar funcionamiento, seguridad y alcance del trabajo.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 60}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_7b6e81e386ff63bb' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'trust_band', 'positive', 'Trust Band 100/100 fontaneros sevilla', 100, 'v80_c11eccb4b3b48f44', '<h2>Garantías prudentes y trabajo responsable</h2><p>Un servicio fiable no promete resultados absolutos sin revisar el caso. Debe trabajar con criterios de criterios de estanqueidad, salubridad y reparación proporcional, explicar limitaciones y evitar datos comerciales no confirmados. La confianza se construye con claridad: qué se hará, qué no se puede asegurar y qué comprobaciones se realizarán al finalizar.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_c11eccb4b3b48f44' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'cta_panel', 'positive', 'Cta Panel 100/100 fontaneros sevilla', 100, 'v80_e99ad3097b2909fd', '<h2>¿Necesita valorar una intervención de fontanería en Sevilla?</h2><p>Explique el síntoma, la zona y si el problema afecta a fuga oculta, presión de agua o llave de paso. Con esa información se puede orientar la intervención y preparar una propuesta más precisa.</p><p><strong>Botón:</strong> Solicitar valoración</p><p><small>Sin promesas automáticas: primero se revisa el caso y después se confirma el alcance.</small></p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 56}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_e99ad3097b2909fd' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'comparison_table', 'positive', 'Comparison Table 100/100 fontaneros sevilla', 100, 'v80_fa1c23a388b3957b', '<h2>Reparar, ajustar o sustituir</h2><table><tr><th>Opción</th><th>Cuándo encaja</th><th>Qué comprobar</th></tr><tr><td>Reparar</td><td>Cuando el fallo está localizado y el elemento conserva vida útil.</td><td>Presión de agua y señales de desgaste.</td></tr><tr><td>Ajustar</td><td>Cuando el problema viene de uso, holgura, presión o configuración.</td><td>Comprobar presión y repetir la prueba.</td></tr><tr><td>Sustituir</td><td>Cuando hay rotura, incompatibilidad o riesgo persistente.</td><td>Material compatible, seguridad y comprobación final.</td></tr></table>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 47}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_fa1c23a388b3957b' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'checklist', 'positive', 'Checklist 100/100 fontaneros sevilla', 100, 'v80_70c24f8fe6865a75', '<h2>Checklist antes de confirmar el servicio</h2><ul><li>Describir el síntoma con palabras sencillas: cuándo ocurre y si se repite.</li><li>Indicar si afecta a llave de paso, sifón o bajante.</li><li>Confirmar barrio o zona de Sevilla, por ejemplo Nervión o Los Remedios.</li><li>Solicitar explicación del alcance antes de aceptar una sustitución completa.</li><li>Comprobar el resultado final con el profesional presente.</li></ul>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 53}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_70c24f8fe6865a75' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'map', 'positive', 'Map 100/100 fontaneros sevilla', 100, 'v80_65d9590a1d357012', '<h2>Cobertura local en Sevilla</h2><p>La cobertura debe comunicarse por zonas reales, no mediante direcciones inventadas. Para fontaneros, tiene sentido organizar la disponibilidad alrededor de Triana, Macarena, áreas residenciales, locales comerciales y comunidades cercanas, siempre confirmando desplazamiento antes de cerrar la intervención.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 40}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_65d9590a1d357012' AND agent_name = 'Content_Writer_01');
INSERT INTO learning_exemplars (agent_name, niche, city, page_type, block_type, polarity, title, score, fingerprint, excerpt, metadata_json) SELECT 'Content_Writer_01', 'fontaneros', 'sevilla', 'service', 'content', 'positive', 'Content 100/100 fontaneros sevilla', 100, 'v80_1b11a32fe3ea4a3e', '<h2>Diagnóstico profesional antes de actuar</h2><p>Una intervención de fontanería bien planteada empieza por entender el síntoma y no por vender una sustitución. El profesional debe observar el contexto, localizar la fuga, revisar bajante y confirmar si el fallo procede de desgaste, instalación previa o uso continuado.</p><p>Este método reduce cambios innecesarios, mejora la explicación del presupuesto y deja al cliente con una decisión más segura.</p>', '{"strengths": ["Precisión técnica sectorial", "Localismo sin inventar NAP", "Tono premium y prudente", "Estructura semántica reutilizable"], "metrics": {"words": 63}, "quality": "100/100 artificial learning V8.0"}' WHERE NOT EXISTS (SELECT 1 FROM learning_exemplars WHERE fingerprint = 'v80_1b11a32fe3ea4a3e' AND agent_name = 'Content_Writer_01');
